        if (teacherFeedbackApprovalCurrent(assessment)) {
            try {
                var generated = normalizeStructuredFeedbackText(studentCriterionLines(working).join('\n\n') + evidenceLimitExplanation(working));
                var storedBody = full.replace(/(?:^|\n\n)(?:Teacher-adjusted total|Total):[^\n]*$/, '').trim();
                useStored = useStored || normalizeStructuredFeedbackText(storedBody) !== generated;
            } catch (ignore) { useStored = true; }
        }
        var lines = [];
