        var firstEntry = panel ? qs(S.bokEntry, panel) : null;
        var assignmentId = firstEntry ? attr(firstEntry, S.cbokAssignmentId) : getAssignmentId();
        var topicEl = panel ? qs(S.cbokProductTitle, panel) : null;
