        var el2 = document.createElement('span'); el2.textContent = ' articles (reduces target)'; el2.setAttribute('style', 'color:#aaa;font-size:11px;');
        er.appendChild(el); er.appendChild(ei); er.appendChild(el2); box.appendChild(er);
        var br = document.createElement('div'); br.setAttribute('style', 'display:flex;gap:10px;justify-content:flex-end;margin-top:16px;');
        var sv = document.createElement('button'); sv.textContent = 'Save'; sv.setAttribute('style', 'padding:10px 18px;background:#8e44ad;color:#fff;border:none;border-radius:6px;cursor:pointer;font-size:13px;font-weight:600;');
        sv.addEventListener('click', function () { var c = parseInt(ei.value, 10) || 0; WEEKLY.setExemption(stud.studentName, c, wid, assignmentId).then(function () { ov.parentNode.removeChild(ov); if (onSave) onSave(); }); });
