    var _weeklyRefreshToken = 0;
    function refreshWeekly(wid, target) {
        var refreshToken = ++_weeklyRefreshToken;
        Promise.all([DB.getAllAssessments(), ROSTER.loadActive()]).then(function (loaded) {
            var assignmentId = _selectedAssignmentId || getAssignmentId();
            var period = _assignmentPeriods.filter(function (candidate) { return candidate.assignmentId === assignmentId; })[0] || { assignmentId: assignmentId, weekId: wid || _currentWeek || '' };
            var cur = assessmentsForPeriod(loaded[0], period);
            var roster = loaded[1];
            WEEKLY.getAllExemptions(wid, assignmentId).then(function (ex) {
                if (refreshToken !== _weeklyRefreshToken) return;
                showWeeklyResults(WEEKLY.calculate(cur, target, 'first', ex, roster.names), wid, target, assignmentId);
            });
        });
    }

