        var ov = document.createElement('dialog');
        ov.id = 'rwbe-debug';
        ov.setAttribute('style', 'all:initial;position:fixed;inset:0;z-index:2147483646;background:rgba(0,0,0,0.8);display:flex;align-items:center;justify-content:center;font-family:system-ui,sans-serif;');

