                row.appendChild(document.createElement('br'));
                var extractionFinal = document.createElement('b'); extractionFinal.style.color = color; extractionFinal.textContent = 'final: ' + d.finalResponseLen + 'ch via ' + d.finalResponseSource; row.appendChild(extractionFinal);
