                    var requiredText = scope === 'all' ? 'DELETE ALL ASSESSMENTS' : 'RESET WEEK';
                    var confirmation = prompt('Reset ' + label + '?\n\nThis removes ' + preview.assessmentCount + ' assessment' + (preview.assessmentCount === 1 ? '' : 's') + ', including ' + preview.teacherRecordCount + ' teacher-approved or adjusted record' + (preview.teacherRecordCount === 1 ? '' : 's') + '. Stored articles and ReadWorks responses are preserved.\n\nType ' + requiredText + ' to continue.');
                    if (confirmation !== requiredText) throw { cancelled: true };
