        btnUp.addEventListener('click', function (event) { event.preventDefault(); event.stopPropagation(); nudgeGradeScore(entry, assessment, SCORE_STEP, btnUp, btnDown); });
        btnDown.addEventListener('click', function (event) { event.preventDefault(); event.stopPropagation(); nudgeGradeScore(entry, assessment, -SCORE_STEP, btnUp, btnDown); });
        stepper.appendChild(btnUp);
        stepper.appendChild(btnDown);
        gradeLeft.appendChild(gradeLabel);
        gradeLeft.appendChild(stepper);
        var gradeActions = document.createElement('div');
        gradeActions.setAttribute('style', 'display:flex;flex-wrap:wrap;align-items:center;justify-content:flex-end;gap:7px;min-width:0;max-width:100%;');
