            var adjustmentText = Number(assessment.coverageAdjustment) > 0 ? ' \u00B7 Ideas \u2212' + assessment.coverageAdjustment : Number(assessment.coverageAdjustment) < 0 ? ' \u00B7 Ideas +' + Math.abs(assessment.coverageAdjustment) : '';
            var rawText = ''; // The explained final calculation is shown with the feedback.
