            coverageLine.title = assessment.coverage.reason || '';
            coverageLine.setAttribute('style', 'margin:-1px 0 7px;padding:5px 7px;background:' + P.insetBg + ';border-radius:4px;color:#a8b1c2;font-size:10px;font-weight:400;');
