            var minorGroups = Number(guard.minorGroups != null ? guard.minorGroups : Object.keys(impactGroups.minor).length) || 0;
            var materialGroups = Number(guard.materialGroups != null ? guard.materialGroups : Object.keys(impactGroups.material).length) || 0;
