    // ── UI Panel ──
    var _panelInjected = false, _panelBtnAssess = null, _panelBtnRetryFailed = null, _panelBtnViewAssess = null, _panelBtnViewArt = null;
    var _currentWeek = null, _currentTarget = 5, _selectedAssignmentId = null, _assignmentPeriods = [];
    function updateCurrentTarget(target) {
        target = parseInt(target, 10);
        if (target < 1 || target > 5) return;
        _currentTarget = target;
        var targetAssignmentId = _selectedAssignmentId || getAssignmentId();
        saveTarget(target, targetAssignmentId);
        rememberAssignmentTarget(targetAssignmentId, target).then(function (periods) { if (Array.isArray(periods)) _assignmentPeriods = periods.slice().sort(comparePeriods); }).catch(function (error) { warn('Could not attach the weekly target to its period: ' + error.message); });
        qsa('.rwbe-target-select').forEach(function (select) { select.value = String(target); });
        if (document.getElementById('rwbe-dashboard')) showDashboard(target);
        var weeklyOverlay = document.getElementById('rwbe-weekly');
        if (weeklyOverlay) refreshWeekly(weeklyOverlay.getAttribute('data-week-id') || _currentWeek, target);
    }
