                if (rows.length !== qsa(S.bokEntry, panel).length) throw new Error('Could not match every response for ' + passage.title + '. Weekly assessment stopped.');
                if (rows.some(function (entry) { return entry.articleTitle !== passage.title; })) throw new Error('Passage identity changed during loading. Weekly assessment stopped.');
