                    var name = cell('', 'left'); name.title = row.studentName + ' · overall score ' + row.overallScore.toFixed(1) + '/10'; name.setAttribute('style', name.getAttribute('style') + 'font-weight:750;font-size:22px;color:#172337;');
                    var missing = Math.max(0, row.target - row.completed);
