                        var weekStats = document.createElement('span'); weekStats.textContent = week.completed + '/' + week.adjustedTarget + ' - Quality ' + week.qualityAvg.toFixed(1) + ' - Weekly ' + week.weeklyScore.toFixed(1); weekStats.setAttribute('style', 'color:#334155;');
                        weekHead.appendChild(weekName); weekHead.appendChild(weekStats); weekBlock.appendChild(weekHead);
